// Screen-registry coverage (Prompts/42 §42.6): every feature folder, role shell and `/app/...` route named in the
// NN.10 sections of Prompts/01–41 (tool/expected_screens.json, generated by backend/scripts/extract_mobile_screens.py)
// exists — folder under lib/features, role key in `roleTabs`, route registered in `ScreenRegistry`.
//
//   dart run tool/check_screen_registry.dart
import 'dart:convert';
import 'dart:io';

void main() {
  final expected = jsonDecode(File('tool/expected_screens.json').readAsStringSync()) as Map<String, dynamic>;
  final routesSrc = File('lib/core/router/routes.dart').readAsStringSync();
  final registrySrc = File('lib/core/router/screen_registry.dart').readAsStringSync();
  final shellsSrc = File('lib/core/router/role_shells.dart').readAsStringSync();
  final constantsSrc = File('lib/core/constants.dart').readAsStringSync();

  final routeByName = {
    for (final m in RegExp(r"static const (\w+) = '([^']+)'").allMatches(routesSrc)) m.group(1)!: m.group(2)!,
  };
  final registered = {
    for (final m in RegExp(r'AppRoutes\.(\w+): ScreenEntry').allMatches(registrySrc))
      if (routeByName[m.group(1)] != null) routeByName[m.group(1)]!,
  };
  final roleConst = {
    for (final m in RegExp(r"static const (\w+) = '([a-z_]+)'").allMatches(constantsSrc)) m.group(2)!: m.group(1)!,
  };
  final shellRoles = {for (final m in RegExp(r'Roles\.(\w+): \[').allMatches(shellsSrc)) m.group(1)!};

  final missing = <String>[];
  expected.forEach((phase, raw) {
    final v = raw as Map<String, dynamic>;
    for (final f in (v['features'] as List).cast<String>()) {
      if (!Directory('lib/features/$f').existsSync()) missing.add('$phase folder features/$f');
    }
    for (final r in (v['roles'] as List).cast<String>()) {
      final name = roleConst[r];
      if (name == null || !shellRoles.contains(name)) missing.add('$phase shell for role $r');
    }
    for (final r in (v['routes'] as List).cast<String>()) {
      if (!registered.contains(r)) missing.add('$phase route $r');
    }
  });
  stdout.writeln('screen registry: ${registered.length} registered routes, ${shellRoles.length} role shells');
  for (final m in missing) {
    stdout.writeln('  MISSING $m');
  }
  stdout.writeln('${missing.length} missing');
  exit(missing.isEmpty ? 0 : 1);
}
